func BaseName(gen int) string { return fmt.Sprintf("base-%d.tbl", gen) }

// PressAndInstall publishes an immutable base before publishing the keep
// record that names it.  Every rename is made durable via the directory.
func PressAndInstall(store string, rows interface{}, seq uint64, gen int, logBytes int64, fence func(*os.File)) error {
	tmp := filepath.Join(store, BaseName(gen)+".tmp")
	final := filepath.Join(store, BaseName(gen))
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)
	if err != nil { return err }
	snapshot := struct {
		Gen int `json:"gen"`
		Seq uint64 `json:"seq"`
		Rows interface{} `json:"rows"`
	}{gen, seq, rows}
	if err = json.NewEncoder(f).Encode(snapshot); err != nil { f.Close(); return err }
	fence(f)
	if err = f.Close(); err != nil { return err }
	if err = os.Rename(tmp, final); err != nil { return err }
	d, err := os.Open(store)
	if err != nil { return err }
	fence(d)
	d.Close()

	keep := Keep{Gen: gen, BaseFile: BaseName(gen), CoveredSeq: seq, LogBytes: logBytes}
	if err = writeKeepTemp(store, keep, fence); err != nil { return err }
	if err = os.Rename(PathFor(store)+".tmp", PathFor(store)); err != nil { return err }
	d, err = os.Open(store)
	if err != nil { return err }
	fence(d)
	return d.Close()
}
